//! Golden tests for the parser: bytecode listings (`luajit -bl`) and syntax error messages
//! (`loadstring`), both generated by the reference binary (tests/fixtures/parse/gen.sh).

use std::fs;
use std::path::{Path, PathBuf};

use luajit::parse;
use luajit::state::Vm;
use luajit::value::Value;

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/parse")
}

fn lua_files(dir: &Path) -> Vec<PathBuf> {
    let mut v: Vec<PathBuf> = fs::read_dir(dir)
        .expect("fixture dir")
        .map(|e| e.expect("dir entry").path())
        .filter(|p| p.extension().is_some_and(|e| e == "lua"))
        .collect();
    v.sort();
    v
}

/// Byte-oriented diff summary: first differing line.
fn first_diff(want: &[u8], got: &[u8]) -> String {
    let w: Vec<&[u8]> = want.split(|&b| b == b'\n').collect();
    let g: Vec<&[u8]> = got.split(|&b| b == b'\n').collect();
    for i in 0..w.len().max(g.len()) {
        let a = w.get(i).copied().unwrap_or(b"<missing>");
        let b = g.get(i).copied().unwrap_or(b"<missing>");
        if a != b {
            return format!(
                "line {}:\n  want: {}\n  got:  {}",
                i + 1,
                String::from_utf8_lossy(a),
                String::from_utf8_lossy(b)
            );
        }
    }
    String::from("(identical lines)")
}

fn run_listing(path: &Path) -> Result<(), String> {
    check_listing(path, "lua.bl", true)
}

/// Non-native frame layout (`luajit -bWl`).
fn run_listing_fr1(path: &Path) -> Result<(), String> {
    check_listing(path, "lua.blw", false)
}

fn check_listing(path: &Path, ext: &str, fr2: bool) -> Result<(), String> {
    let name = path.file_name().unwrap().to_str().unwrap();
    let src = fs::read(path).unwrap();
    let want = fs::read(path.with_extension(ext)).map_err(|e| format!("{name}: no golden: {e}"))?;
    let mut vm = Vm::new();
    let chunkname = format!("@{name}");
    let pt = parse::parse_ex(&mut vm, &src, chunkname.as_bytes(), fr2).map_err(|e| {
        let msg = match e.value {
            Value::Str(s) => s.to_string_lossy(),
            _ => String::from("?"),
        };
        format!("{name}: parse failed: {msg}")
    })?;
    let got = parse::bclist(pt);
    if got != want {
        return Err(format!("{name}: listing differs at {}", first_diff(&want, &got)));
    }
    Ok(())
}

fn run_error(path: &Path) -> Result<(), String> {
    let name = path.file_name().unwrap().to_str().unwrap();
    let src = fs::read(path).unwrap();
    let want = fs::read(path.with_extension("err")).map_err(|e| format!("{name}: no golden: {e}"))?;
    let mut vm = Vm::new();
    // loadstring's default chunk name is the source itself.
    match parse::parse(&mut vm, &src, &src) {
        Ok(_) => Err(format!("{name}: compiled, expected error")),
        Err(e) => {
            assert_eq!(e.kind, luajit::error::ErrorKind::Syntax, "{name}: error kind");
            let got = match e.value {
                Value::Str(s) => s.as_bytes().to_vec(),
                _ => return Err(format!("{name}: non-string error value")),
            };
            if got != want {
                return Err(format!(
                    "{name}:\n  want: {}\n  got:  {}",
                    String::from_utf8_lossy(&want),
                    String::from_utf8_lossy(&got)
                ));
            }
            Ok(())
        }
    }
}

fn run_all(files: Vec<PathBuf>, f: fn(&Path) -> Result<(), String>) {
    assert!(!files.is_empty(), "no fixtures found");
    let total = files.len();
    let failures: Vec<String> = files
        .iter()
        .filter_map(|p| match std::panic::catch_unwind(|| f(p)) {
            Ok(r) => r.err(),
            Err(_) => Some(format!("{}: panicked", p.display())),
        })
        .collect();
    if !failures.is_empty() {
        panic!("{} of {} fixtures failed:\n{}", failures.len(), total, failures.join("\n"));
    }
}

#[test]
fn bytecode_listings_match_reference() {
    run_all(lua_files(&fixture_dir()), run_listing);
}

#[test]
fn syntax_errors_match_reference() {
    run_all(lua_files(&fixture_dir().join("errors")), run_error);
}

#[test]
fn bytecode_listings_fr1_match_reference() {
    run_all(lua_files(&fixture_dir()), run_listing_fr1);
}
